@'
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
const root=fs.mkdtempSync(path.join(os.tmpdir(),'dip-longitudinal-stress-preflight-'));
for(const file of ['cart.mjs','summary.mjs','receipt.mjs','inventory.mjs','returns.mjs','pipeline.mjs'])fs.writeFileSync(path.join(root,file),'// deliberately empty module\n');
const text=execFileSync(process.execPath,['scripts/longitudinal-stress.mjs','--project-worker',root,'0'],{encoding:'utf8',windowsHide:true,maxBuffer:1048576});
const result=JSON.parse(text.split(/\r?\n/).findLast(l=>l.startsWith('STRESS_RESULT:')).slice(14));
assert.equal(result.total,2304);assert.equal(result.passed,0);assert.equal(result.loadErrors.length,0);
console.log('Isolated stress-worker preflight detected all 2304 absent-export checks.');
const resolved=fs.realpathSync(root),tmp=fs.realpathSync(os.tmpdir());
assert.ok(resolved.startsWith(tmp+path.sep)&&path.basename(resolved).startsWith('dip-longitudinal-stress-preflight-'));
fs.rmSync(resolved,{recursive:true,force:true});
'@ | node --input-type=module
npx prettier --write scripts/longitudinal-stress-evidence.mjs
